<section class="page-intro"><div class="container-page"><p class="eyebrow">The BrandBuzz journal</p><h1>A few good ideas<br><span class="text-brand-500">to get you thinking.</span></h1><p class="text-muted text-lg mt-6 max-w-xl">Practical notes on brand, creativity and making the most of your digital presence.</p></div></section><section class="container-page section-space"><form method="get" class="flex gap-3 max-w-xl mb-10" action="<?= e(page_url('blog')) ?>" role="search"><label class="sr-only" for="blog-search">Search articles</label><input id="blog-search" type="search" name="q" value="<?= e($search) ?>" placeholder="Find an article…" maxlength="100"><button class="btn btn-primary" type="submit"><?= icon('search','w-4 h-4') ?><span>Search</span></button></form><div class="grid md:grid-cols-2 lg:grid-cols-3 gap-7"><?php foreach($items as $post): ?><article class="card overflow-hidden"><a href="<?= e(page_url('blog',['slug'=>$post['slug']])) ?>"><img class="w-full aspect-[16/10] object-cover bg-brand-50" src="<?= e(media($post['image'])) ?>" width="640" height="400" alt="<?= e($post['title']) ?>" loading="lazy"></a><div class="p-6"><p class="eyebrow mb-3"><?= e($post['category']) ?></p><h2 class="text-xl font-bold"><a class="hover:text-brand-600" href="<?= e(page_url('blog',['slug'=>$post['slug']])) ?>"><?= e($post['title']) ?></a></h2><p class="text-sm text-muted mt-3"><?= e($post['excerpt']) ?></p><div class="flex justify-between items-center mt-6 gap-3"><span class="text-xs text-muted"><?= e(date('M j, Y',strtotime($post['created_at']))) ?></span><a class="link-arrow" href="<?= e(page_url('blog',['slug'=>$post['slug']])) ?>">Read article <?= icon('arrow','w-4 h-4') ?></a></div></div></article><?php endforeach ?></div><?php if(!$items): ?><div class="card p-10 text-center"><h2 class="text-2xl font-bold">No articles found.</h2><p class="text-muted mt-3">Try another phrase or browse all articles.</p><a class="btn btn-outline mt-5" href="<?= e(page_url('blog')) ?>">All articles</a></div><?php endif ?><?php view('layouts/pagination',['page'=>$page,'pages'=>$pages,'paginationUrl'=>page_url('blog'),'paginationParams'=>['q'=>$search]]); ?></section>
